INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('debt', 'state', '«اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ»', 'O Allaah, Heer van de zeven hemelen en Heer van de aarde en Heer van de geweldige Troon, onze Heer en Heer van alles, Splijter van de korrel en de pit, Neerzender van de Tawraat, de Indjiel en de Furqaan: ik zoek toevlucht bij U tegen het kwaad van alles waarvan U de voorlok vasthoudt. O Allaah, U bent de Eerste, er is niets voor U; U bent de Laatste, er is niets na U; U bent de Zichtbare, er is niets boven U; U bent de Verborgene, er is niets onder U. Los voor ons de schuld af en maak ons vrij van armoede.', '', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بقضاء الدين والغنى', 'toestand', 'state/situation', 1, 181),('waswas', 'state', 'مَنْ وَجَدَ شَيْئًا مِنْ ذَلِكَ فَلْيَسْتَعِذْ بِاللَّهِ وَلْيَنْتَهِ، وَلْيَقُلْ: «آمَنْتُ بِاللَّهِ وَرُسُلِهِ»', 'Ik geloof in Allaah en Zijn boodschappers — en men houdt op (met de gedachte) en zoekt toevlucht bij Allaah.', 'I believe in Allaah and His messengers — and one desists and seeks refuge in Allaah.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وسوسة الشيطان في أصل الإيمان', 'toestand', 'state/situation', 1, 182),('waswas', 'state', 'ذاك شيطان يقال له خِنزَب، فإذا أحسه فليتعوذ بالله منه، وليتفل عن يساره ثلاثا', 'Ik zoek toevlucht bij Allaah tegen de vervloekte shaytaan — en men spuugt driemaal licht naar de linkerkant.', 'I seek refuge in Allaah from the accursed devil — and one spits lightly to the left three times.', '', '', '', 'الأجر مبين في القصة: «ففعلت ذلك فأذهبه الله عني».', 'De beloning is toegelicht in het verhaal: ''ik deed dat en Allaah verdreef het van mij''.', 'The reward is explained in the account: ''I did that and Allaah removed it from me''.', 'الوسوسة في الصلاة والقراءة', 'toestand', 'state/situation', 1, 183),('difficulty', 'state', '«اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا»', 'O Allaah, niets is gemakkelijk behalve wat U gemakkelijk maakt, en U maakt het moeilijke — wanneer U wilt — gemakkelijk.', 'O Allaah, nothing is easy except what You make easy, and You make the difficult — when You will — easy.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بتيسير الصعب', 'toestand', 'state/situation', 1, 184),('sin_majlis', 'state', 'إلا غفر الله له، ثم قرأ: ﴿وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ﴾ [آل عمران: 135]', 'Wie een zonde begaat, verricht een goede woedoe, bidt twee rak3ah en vraagt Allaah om vergeving; dan wordt hem vergeven.', 'Whoever commits a sin, performs ablution well, prays two rak3ahs and seeks Allaah''s forgiveness — he is forgiven.', '', '', '', 'الأجر منصوص: «إلا غفر الله له».', 'De beloning is uitdrukkelijk: ''of Allaah vergeeft hem''.', 'The reward is stated: ''except that Allaah forgives him''.', 'ما من عبد يذنب ذنبا', 'toestand', 'state/situation', 1, 185),('sin_majlis', 'state', '«سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ»', 'Verheven bent U, o Allaah, en aan U alle lof; ik getuig dat er geen god is behalve U; ik vraag U om vergeving en keer berouwvol tot U terug — de kaffaarah van de bijeenkomst.', 'Glory and praise be to You, O Allaah; I bear witness that none has the right to be worshipped except You; I seek Your forgiveness and repent to You — the expiation of the gathering.', '', '', '', 'الأجر منصوص: يُغفر له ما كان في مجلسه ذلك.', 'De beloning is uitdrukkelijk: hem wordt vergeven wat in die bijeenkomst voorviel.', 'The reward is stated: he is forgiven what occurred in that gathering.', 'كفارة المجلس', 'toestand', 'state/situation', 1, 186),('seeing_afflicted', 'state', '«الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا»', 'Alle lof zij Allaah, Die mij heeft gevrijwaard van datgene waarmee Hij jou heeft beproefd, en mij ruimschoots heeft bevoorrecht boven velen van wie Hij heeft geschapen. (In stilte gezegd.)', 'All praise is for Allaah who spared me that with which He tried you and favoured me greatly over many of those He created. (Said quietly.)', '', '', '', 'الأجر منصوص: «لم يصبه ذلك البلاء».', 'De beloning is uitdrukkelijk: ''die beproeving zal hem niet treffen''.', 'The reward is stated: ''that affliction will not befall him''.', 'من رأى مبتلى فقال ــ', 'toestand', 'state/situation', 1, 187),('weather', 'state', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ»', 'O Allaah, ik vraag U het goede ervan, het goede dat erin is en het goede waarmee zij is gezonden, en ik zoek toevlucht bij U tegen het kwade ervan, het kwade dat erin is en het kwade waarmee zij is gezonden.', 'O Allaah, I ask You for its good, the good within it and the good with which it was sent, and I seek refuge in You from its evil, the evil within it and the evil with which it was sent.', 'يقوله عند هبوب الريح الشديدة كلما هاجت، سرا أو جهرا، ولا يسب الريح؛ فإنها من رَوح الله تأتي بالرحمة وتأتي بالعذاب.', 'Zegt men bij het opsteken van een harde wind telkens als hij opsteekt, in stilte of hoorbaar, en men vervloekt de wind niet; want hij komt uit Allaahs barmhartigheid.', 'Said upon a strong wind rising, whenever it rises, silently or aloud; one does not curse the wind, for it comes from Allaah''s mercy.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند هبوب الريح', 'toestand', 'state/situation', 1, 188),('weather', 'state', '«سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيفَتِهِ»', 'Verheven is Degene voor Wie de donder met Zijn lof de verhevenheid prijst, en ook de engelen, uit ontzag voor Hem.', 'Glory be to the One whom the thunder glorifies with His praise, and the angels too, out of awe of Him.', 'كان ابن الزبير رضي الله عنهما إذا سمع الرعد ترك الحديث وقاله؛ فيقطع الكلام ويقوله عند كل رعدة، ولم يثبت في الرعد دعاء مرفوع.', 'Ibn az-Zubayr (moge Allaah tevreden over hen zijn) staakte bij het horen van de donder het gesprek en zei het; men onderbreekt dus het spreken en zegt het bij elke donderslag.', 'Ibn az-Zubayr (may Allaah be pleased with them) would stop talking on hearing the thunder and say it; so one interrupts speech and says it at every thunderclap.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا سمع الرعد قال', 'toestand', 'state/situation', 1, 189),('weather', 'state', '«اللَّهُمَّ صَيِّبًا نَافِعًا»', 'O Allaah, (maak het) een voordelige regen.', 'O Allaah, (make it) a beneficial rain.', 'يقوله عند أول رؤية المطر نازلا، ويستحب أن يتعرض له بشيء من بدنه؛ فقد حسر النبي صلى الله عليه وسلم ثوبه حتى أصابه المطر وقال: «إنه حديث عهد بربه» [مسلم (898)]، والدعاء حال نزوله مرجو الإجابة.', 'Zegt men bij het eerste zien van de vallende regen, en het is aanbevolen zich eraan bloot te stellen met een deel van het lichaam; de Profeet (vrede en zegeningen zij met hem) ontblootte (zijn lichaam ervoor).', 'Said at first seeing the rain fall, and it is recommended to expose part of one''s body to it; the Prophet (peace and blessings be upon him) uncovered (his body to it).', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا رأى المطر قال', 'toestand', 'state/situation', 1, 190),('weather', 'state', 'يَكْشِفُ شَيْئًا مِنْ بَدَنِهِ أَوْ ثَوْبِهِ لِيُصِيبَهُ أَوَّلُ الْمَطَرِ، مَعَ دُعَاءِ «اللَّهُمَّ صَيِّبًا نَافِعًا» الْمُتَقَدِّمِ', 'Men ontbloot iets van zijn lichaam of kleding zodat de eerste regen hem raakt, met de smeekbede: Allaahumma sayyiban naafi3an.', 'One uncovers part of his body or garment so the first rain touches him, with the supplication: Allaahumma sayyiban naafi3an.', 'يتعرض له تبركا بقرب عهده بخلق ربه، من غير مشقة ولا تعريض للضرر.', 'Men stelt zich eraan bloot als zegening wegens de recentheid van zijn ontstaan bij zijn Heer, zonder ongemak of blootstelling aan schade.', 'One exposes oneself to it as a blessing because of its recent origin from its Lord, without hardship or exposure to harm.', 'العلة منصوصة: «لأنه حديث عهد بربه».', 'De reden is uitdrukkelijk: ''omdat het vers van zijn Heer komt'' (recent geschapen).', 'The reason is stated: ''because it has recently come from its Lord''.', 'ومن هيئته ﷺ عند أول المطر: التعرض له', 'toestand', 'state/situation', 1, 191),('weather', 'state', '«مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ»', 'Wij hebben regen gekregen door de gunst van Allaah en Zijn barmhartigheid.', 'We have been given rain by the bounty of Allaah and His mercy.', 'يقوله إذا أصبح بعد ليلة المطر أو بعد انقضائه، مضيفا النعمة إلى الله وحده، ويحذر قول: مُطرنا بنوء كذا؛ فإنه كفر بالنعمة كما في الحديث نفسه.', 'Zegt men in de ochtend na een regennacht of na het ophouden ervan, de gunst enkel aan Allaah toeschrijvend, en men hoedt zich te zeggen: wij kregen regen door een sterrenstand.', 'Said in the morning after a rainy night or after it ceases, attributing the favour to Allaah alone; one avoids saying: we were given rain by a star.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وبعد نزول المطر يقول', 'toestand', 'state/situation', 1, 192),('animal_sounds', 'state', '«فَإِنَّهُ رَأَى شَيْطَانًا»', 'Bij het horen van hanengekraai vraagt men Allaah om Zijn gunst (want de haan zag een engel); bij ezelgebalk zoekt men toevlucht bij Allaah tegen de shaytaan (want hij zag een shaytaan).', 'On hearing a rooster crow one asks Allaah of His bounty (it saw an angel); on a donkey''s bray one seeks refuge in Allaah from Satan (it saw a devil).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند سماع الديكة والحمير ليلا', 'toestand', 'state/situation', 1, 193),('animal_sounds', 'state', '«فَإِنَّهُنَّ يَرَيْنَ مَا لَا تَرَوْنَ»', 'Bij het horen van hondengeblaf en ezelgebalk in de nacht zoekt men toevlucht bij Allaah; zij zien wat wij niet zien.', 'On hearing dogs barking and donkeys braying at night one seeks refuge in Allaah; they see what you do not see.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا سمعتم نباح الكلاب ونهيق', 'toestand', 'state/situation', 1, 194),('pain_ruqyah', 'state', '«بِسْمِ اللَّهِ» ثَلَاثًا، ثُمَّ قَالَ سَبْعَ مَرَّاتٍ: «أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ»', 'In de Naam van Allaah (driemaal, met de hand op de pijnlijke plek); daarna zevenmaal: Ik zoek toevlucht bij Allaah en Zijn macht tegen het kwade van wat ik voel en vrees.', 'In the Name of Allaah (three times, hand on the painful spot); then seven times: I seek refuge in Allaah and His power from the evil of what I feel and fear.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'من اشتكى ألما في جسده', 'toestand', 'state/situation', 1, 195),('pain_ruqyah', 'state', '«اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَاسَ، اشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا»', 'O Allaah, Heer van de mensen, neem het leed weg en genees; U bent de Genezer. Er is geen genezing behalve Uw genezing: een genezing die geen ziekte achterlaat.', 'O Allaah, Lord of mankind, remove the harm and cure; You are the Healer. There is no cure except Your cure: a cure that leaves no illness behind.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'رقية النبي ﷺ', 'toestand', 'state/situation', 1, 196),('pain_ruqyah', 'state', '«بِسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ، بِسْمِ اللَّهِ أَرْقِيكَ»', 'In de Naam van Allaah beveilig ik jou met roeqyah, tegen alles wat jou schaadt, tegen het kwade van elke ziel of elk afgunstig oog. Moge Allaah jou genezen; in de Naam van Allaah beveilig ik jou met roeqyah.', 'In the Name of Allaah I perform ruqyah over you, from everything that harms you, from the evil of every soul or envious eye. May Allaah cure you; in the Name of Allaah I perform ruqyah over you.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'رقية جبريل عليه السلام', 'toestand', 'state/situation', 1, 197),('evil_eye', 'state', '«أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ، مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ»', 'Ik plaats jullie beiden onder de bescherming van de volmaakte Woorden van Allaah, tegen elke shaytaan en elk schadelijk dier, en tegen elk treffend (boos) oog — de bescherming van de kinderen.', 'I commend you both to the protection of Allaah''s perfect Words, from every devil and harmful creature, and from every evil eye — the protection of children.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'تعويذ النبي ﷺ الحسن والحسين', 'toestand', 'state/situation', 1, 198),('evil_eye', 'state', '«فَإِنَّ الْعَيْنَ حَقٌّ»، وَمِنْهُ قَوْلُهُ: «أَلَّا بَرَّكْتَ»', 'Wie iets bewondert, vraagt om zegen (tabriek): moge Allaah het zegenen; want het boze oog is werkelijkheid.', 'Whoever admires something invokes blessing (tabreek): may Allaah bless it; for the evil eye is real.', '', '', '', 'الأجر مبين في القصة: بالتبريك تندفع العين، وبالاغتسال يعافى المَعين بإذن الله.', 'De beloning is toegelicht in het verhaal: door de zegenbede wordt het boze oog afgeweerd, en door de wassing geneest de getroffene met Allaahs toestemming.', 'The reward is explained in the account: by invoking blessing the evil eye is repelled, and by washing the afflicted is healed by Allaah''s leave.', 'إذا رأى ما يعجبه', 'toestand', 'state/situation', 1, 199),('evil_eye', 'state', '«الْعَيْنُ حَقٌّ، وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا»', 'Het boze oog is werkelijkheid; wanneer men jullie vraagt je te wassen (voor de getroffene), was je dan.', 'The evil eye is real; and if you are asked to wash (for the afflicted), then wash.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا أصاب العائنُ أحدا أُمر أن يغتسل له', 'toestand', 'state/situation', 1, 200);